/**
 * Java Service 生成器
 * IR → Service 接口（generated/service，可覆盖）
 *    + ServiceImpl 骨架（service/，仅首次创建，绝不覆盖手写实现）
 *
 * 架构：
 *   - 接口由 api 段推导，方法签名固定，随模型重新生成
 *   - 实现类由 handServiceDir 指定，人填业务逻辑
 *   - 实现类首次创建骨架；若仍是纯骨架（全 TODO），则随模型刷新以同步签名；
 *     一旦有人填入业务逻辑（出现 return），即受保护不再覆盖。
 *
 * 路径参数类型由 api.pathParams 显式声明（C28 保证存在）。
 */
import { writeFileSync, mkdirSync, existsSync, readFileSync } from 'fs'
import { join } from 'path'

const HEADER = [
  '// AUTO-GENERATED by polyforge. DO NOT EDIT.',
  '// 源：模型定义的 api 段',
  '',
]

// 包名由 generateJavaService 的 basePackage 参数派生（见文件末尾）

function cap(s) { return s.charAt(0).toUpperCase() + s.slice(1) }
function camel(s) { return s.split(/[-_]/).filter(Boolean).map(cap).join('') }

/** domain → Service 名，如 auth → AuthService，award-notice → AwardNoticeService */
function serviceName(domain) { return camel(domain) + 'Service' }

/** 基础类型 → Java 类型（供 pathParams 使用） */
const PRIM = {
  string: 'String', text: 'String',
  int: 'Integer', long: 'Long',
  number: 'BigDecimal', decimal: 'BigDecimal',
  boolean: 'Boolean',
}

/** 从 path 提取路径参数名（:id → id） */
function pathParams(path) {
  const names = []
  const re = /:([a-zA-Z][a-zA-Z0-9]*)/g
  let m
  while ((m = re.exec(path)) !== null) names.push(m[1])
  return names
}

/**
 * 路径参数的 Java 类型。
 * C28 保证每个路径参数都在 pathParams 声明，故直接读取；
 * 遇到无法映射的类型抛错（fail fast）。
 */
function pathParamJavaType(api, name) {
  const def = api.pathParams[name]
  if (def.type === 'id') {
    return (def.idType === 'string' || def.idType === 'uuid') ? 'String' : 'Long'
  }
  const t = PRIM[def.type]
  if (!t) {
    throw new Error('无法映射路径参数类型: api ' + api.name + ' :' + name + ' = ' + def.type)
  }
  return t
}

/** 方法参数列表（路径参数 → input → query） */
function methodParams(api) {
  const params = []
  for (const p of pathParams(api.path)) params.push({ type: pathParamJavaType(api, p), name: p })
  if (api.input) params.push({ type: api.input, name: 'form' })
  if (api.query) params.push({ type: 'Map<String, Object>', name: 'query' })
  return params
}

function paramsStr(api) {
  const ps = methodParams(api)
  return ps.map((p) => p.type + ' ' + p.name).join(', ')
}

function returnType(api) { return api.output || 'void' }

/** 按 domain 分组 apis */
function groupByDomain(apis) {
  const map = new Map()
  for (const api of apis) {
    const d = api.domain
    if (!map.has(d)) map.set(d, [])
    map.get(d).push(api)
  }
  return map
}

function renderService(domain, apis, PKG_SERVICE, PKG_DTO) {
  const name = serviceName(domain)
  const lines = [...HEADER]
  lines.push('package ' + PKG_SERVICE + ';')
  lines.push('')

  const imports = new Set()
  for (const api of apis) {
    if (api.input) imports.add(PKG_DTO + '.' + api.input)
    if (api.output) imports.add(PKG_DTO + '.' + api.output)
  }
  if (apis.some((a) => a.query)) imports.add('java.util.Map')
  if (apis.some((a) => methodParams(a).some((p) => p.type === 'BigDecimal'))) imports.add('java.math.BigDecimal')
  for (const imp of [...imports].sort()) lines.push('import ' + imp + ';')
  if (imports.size) lines.push('')

  lines.push('public interface ' + name + ' {')
  for (const api of apis) {
    lines.push('')
    lines.push('    /** ' + (api.summary || api.name) + ' */')
    lines.push('    ' + returnType(api) + ' ' + api.name + '(' + paramsStr(api) + ');')
  }
  lines.push('}')
  return lines.join('\n') + '\n'
}

function renderImpl(domain, apis, PKG_SERVICE, PKG_DTO, PKG_IMPL) {
  const svc = serviceName(domain)
  const impl = svc + 'Impl'
  const lines = []
  lines.push('// 手写实现：纯骨架会被 polyforge 刷新；填入业务逻辑后即受保护。')
  lines.push('package ' + PKG_IMPL + ';')
  lines.push('')
  lines.push('import ' + PKG_SERVICE + '.' + svc + ';')

  const imports = new Set()
  for (const api of apis) {
    if (api.input) imports.add(PKG_DTO + '.' + api.input)
    if (api.output) imports.add(PKG_DTO + '.' + api.output)
  }
  if (apis.some((a) => a.query)) imports.add('java.util.Map')
  if (apis.some((a) => methodParams(a).some((p) => p.type === 'BigDecimal'))) imports.add('java.math.BigDecimal')
  for (const imp of [...imports].sort()) lines.push('import ' + imp + ';')
  lines.push('import org.springframework.stereotype.Service;')
  lines.push('')
  lines.push('@Service')
  lines.push('public class ' + impl + ' implements ' + svc + ' {')
  for (const api of apis) {
    lines.push('')
    lines.push('    @Override')
    lines.push('    public ' + returnType(api) + ' ' + api.name + '(' + paramsStr(api) + ') {')
    lines.push('        throw new UnsupportedOperationException("TODO: ' + api.name + '");')
    lines.push('    }')
  }
  lines.push('}')
  return lines.join('\n') + '\n'
}

/**
 * 判断已存在的 Impl 是否为「纯骨架」（未被人填过业务逻辑）。
 * 判据：方法体数量与 throw TODO 数量一致，且剥掉注释后无 return。
 * 纯骨架 → 可安全覆盖（用于同步签名变更）；否则保护，不覆盖。
 *
 * 必须先剥注释：生成器写的头注释里有 "return" 这个词，
 * 直接对全文做 /\breturn\b/ 会恒为 true，导致所有 Impl 永远被保护。
 */
function isPureSkeleton(content, methodCount) {
  const stripped = content
    .replace(/\/\*[\s\S]*?\*\//g, '')
    .replace(/\/\/[^\n]*/g, '')
  const throwCount = (stripped.match(/throw new UnsupportedOperationException/g) || []).length
  const hasReturn = /\breturn\b/.test(stripped)
  return throwCount === methodCount && !hasReturn
}

export function generateJavaService(ir, outRoot, handRoot, basePackage) {
  const PKG_SERVICE = basePackage + '.generated.service'
  const PKG_DTO = basePackage + '.generated.dto'
  const PKG_IMPL = basePackage + '.service'
  const dir = join(outRoot, 'service')
  if (!existsSync(dir)) mkdirSync(dir, { recursive: true })
  const implDir = join(handRoot, 'service')
  if (!existsSync(implDir)) mkdirSync(implDir, { recursive: true })

  const byDomain = groupByDomain(ir.apis)
  let ifaceCount = 0
  let implCreated = 0
  let implRefreshed = 0
  let implKept = 0
  for (const [domain, apis] of byDomain) {
    const svc = serviceName(domain)
    writeFileSync(join(dir, svc + '.java'), renderService(domain, apis, PKG_SERVICE, PKG_DTO), 'utf-8')
    ifaceCount++

    const implPath = join(implDir, svc + 'Impl.java')
    if (!existsSync(implPath)) {
      writeFileSync(implPath, renderImpl(domain, apis, PKG_SERVICE, PKG_DTO, PKG_IMPL), 'utf-8')
      implCreated++
      continue
    }
    // 已存在：纯骨架则覆盖以同步签名，有人手写逻辑则保护跳过
    const existing = readFileSync(implPath, 'utf-8')
    if (isPureSkeleton(existing, apis.length)) {
      writeFileSync(implPath, renderImpl(domain, apis, PKG_SERVICE, PKG_DTO, PKG_IMPL), 'utf-8')
      implRefreshed++
    } else {
      implKept++
    }
  }
  console.log(
    '  [java/service] ' + ifaceCount + ' 个接口 → ' + dir +
    '；骨架 新建 ' + implCreated + ' / 刷新 ' + implRefreshed + ' / 保护 ' + implKept + ' → ' + implDir
  )
}
